const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.box}</svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SECTORS={
  inspections:{name:'Inspecciones de carga',short:'Inspecciones',icon:'truck',unit:'Inspección',plural:'inspecciones',prefix:'INS',entity:'Carga / unidad',placeholder:'Contenedor CGFU-2048',description:'Verifica cargas, documenta hallazgos y acompaña cada inspección hasta su cierre.',flowName:'Inspección de recepción',fieldIntro:'Los datos que necesita una operación de carga.',fields:[{key:'plate',label:'Placa del vehículo',placeholder:'DEM-1024',sample:'DEM-1024'},{key:'cargo',label:'Tipo de carga',placeholder:'Ej. Cacao en sacos',sample:'Cacao en sacos · 24 toneladas'},{key:'location',label:'Punto de inspección',placeholder:'Ej. Bodega Norte',sample:'Bodega Norte · Andén 03'}],checks:['Integridad de la carga','Documentación de transporte','Condiciones del vehículo'],sampleEntity:'Contenedor CGFU-2048',sampleTitle:'Recepción de cacao',sampleNotes:'Datos ficticios. Carga recibida en condiciones adecuadas, sin novedades visibles.',specificRule:'Lista de carga, documentos de transporte y punto de recepción.'},
  rental:{name:'Alquiler de vehículos',short:'Vehículos',icon:'car',unit:'Entrega',plural:'entregas',prefix:'ALQ',entity:'Vehículo',placeholder:'Sedán demo · DEM-204',description:'Controla entregas de vehículos, revisa sus condiciones y documenta cada operación.',flowName:'Entrega de vehículo',fieldIntro:'Los datos que necesita la entrega de un vehículo.',fields:[{key:'customer',label:'Cliente de ejemplo',placeholder:'Ej. Cliente Demo A',sample:'Cliente Demo A'},{key:'mileage',label:'Kilometraje',placeholder:'Ej. 24500',sample:'24500',type:'number'},{key:'return',label:'Fecha de devolución',sample:'2026-11-02',type:'date'}],checks:['Carrocería y accesorios revisados','Nivel de combustible verificado','Contrato de ejemplo validado'],sampleEntity:'Sedán demo · DEM-204',sampleTitle:'Entrega de vehículo compacto',sampleNotes:'Datos ficticios. Entrega simulada con tanque lleno y sin daños visibles.',specificRule:'Kilometraje, fecha de devolución y condiciones de entrega. No incluye cobros ni reservas.'},
  maintenance:{name:'Mantenimiento técnico',short:'Mantenimiento',icon:'tool',unit:'Orden',plural:'órdenes',prefix:'MTO',entity:'Equipo',placeholder:'Router demo · RT-018',description:'Organiza revisiones de equipos, asigna técnicos y da seguimiento a cada intervención.',flowName:'Revisión preventiva',fieldIntro:'Los datos que necesita una intervención técnica.',fields:[{key:'serial',label:'Serie del equipo',placeholder:'Ej. DEMO-RT-018',sample:'DEMO-RT-018'},{key:'location',label:'Ubicación del equipo',placeholder:'Ej. Sede demo',sample:'Sede demo · Sala de redes'},{key:'priority',label:'Prioridad',sample:'Media',type:'select',options:['Baja','Media','Alta']}],checks:['Diagnóstico inicial realizado','Funcionamiento verificado','Área de trabajo despejada'],sampleEntity:'Router demo · RT-018',sampleTitle:'Revisión de conectividad',sampleNotes:'Datos ficticios. Se simula una revisión de conectividad y limpieza del equipo.',specificRule:'Serie, prioridad y comprobaciones técnicas. No incluye inventario de repuestos.'}
};
const OWNERS=['Valeria Torres','Andrés Molina','Lucía Pérez'];
const STORAGE_KEY='cargoflow-lab-v1';
let storageOK=true,view='overview',tableFilter='all',search='',compareFrom='inspections',compareTo='rental',mobileOpen=false,currentModal=null,lastFocus=null,toastTimer;
function defaultConfig(key){const s=SECTORS[key];return {name:s.flowName,labels:key==='rental'?['Preparada','En verificación','Entregada']:key==='maintenance'?['Registrada','En diagnóstico','Resuelta']:['Registrada','En revisión','Finalizada'],review:true,requireChecklist:true,requireEvidence:false,requiredFields:Object.fromEntries(s.fields.map(f=>[f.key,true])),version:1};}
function steps(config){return config.review?config.labels:[config.labels[0],config.labels[2]];}
function seedState(){
  const result={schema:1,selected:'inspections',configs:{},records:[],next:19,journey:{sector:false,config:false,record:false,status:false},tour:true};
  for(const key of Object.keys(SECTORS))result.configs[key]=defaultConfig(key);
  const data=[
    ['inspections','Recepción de cacao','Contenedor CGFU-2048',1,0,'2026-10-26T09:35:00-05:00'],
    ['inspections','Verificación de carga seca','Camión demo · DEM-613',0,1,'2026-10-26T09:10:00-05:00'],
    ['inspections','Despacho de plátano','Contenedor CGFU-1082',2,2,'2026-10-26T08:45:00-05:00'],
    ['inspections','Control de recepción','Camión demo · DEM-420',1,0,'2026-10-25T16:20:00-05:00'],
    ['inspections','Inspección de contenedor','Contenedor CGFU-3061',2,1,'2026-10-25T14:30:00-05:00'],
    ['inspections','Recepción de materia prima','Camión demo · DEM-738',0,2,'2026-10-25T11:15:00-05:00'],
    ['rental','Entrega de vehículo compacto','Sedán demo · DEM-204',0,1,'2026-10-26T09:15:00-05:00'],
    ['rental','Entrega de SUV','SUV demo · DEM-880',1,0,'2026-10-26T08:30:00-05:00'],
    ['rental','Entrega de camioneta','Camioneta demo · DEM-913',2,2,'2026-10-25T16:00:00-05:00'],
    ['maintenance','Revisión de conectividad','Router demo · RT-018',0,0,'2026-10-26T09:00:00-05:00'],
    ['maintenance','Mantenimiento preventivo','Switch demo · SW-012',1,1,'2026-10-26T08:00:00-05:00'],
    ['maintenance','Diagnóstico de acceso','Controlador demo · AC-034',2,2,'2026-10-25T15:00:00-05:00']
  ];
  data.forEach((d,i)=>{const [sector,title,entity,status,owner,date]=d;const cfg=structuredClone(result.configs[sector]);const s=SECTORS[sector];result.records.push({id:`${s.prefix}-${String(i+1).padStart(4,'0')}`,sector,title,entity,status,owner:OWNERS[owner],date,config:cfg,fields:Object.fromEntries(s.fields.map(f=>[f.key,f.sample])),checks:s.checks.map(()=>true),evidence:true,notes:'Registro ficticio para explorar CargoFlow. No corresponde a una operación real.',history:Array.from({length:status+1},(_,n)=>({label:n===0?'Registro creado':`Estado: ${steps(cfg)[n]}`,date:new Date(new Date(date).getTime()+n*60000).toISOString()}))});});
  return result;
}
function loadState(){try{const parsed=JSON.parse(localStorage.getItem(STORAGE_KEY));if(parsed?.schema===1&&SECTORS[parsed.selected]&&Object.keys(SECTORS).every(k=>parsed.configs?.[k]?.labels?.length===3)&&Array.isArray(parsed.records)&&parsed.journey)return parsed;}catch{storageOK=false;}return seedState();}
let state=loadState();
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{storageOK=false;toast('El navegador no permite guardar. Los cambios durarán mientras mantengas esta página abierta.');}}
const sector=()=>SECTORS[state.selected];
const config=()=>state.configs[state.selected];
const records=()=>state.records.filter(r=>r.sector===state.selected);
const initials=name=>name.split(' ').map(p=>p[0]).slice(0,2).join('');
const fmtDate=date=>new Date(date).toLocaleDateString('es-EC',{day:'2-digit',month:'short',timeZone:'America/Guayaquil'}).replace('.','');
const fmtTime=date=>new Date(date).toLocaleTimeString('es-EC',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'America/Guayaquil'});
const isComplete=r=>r.status===steps(r.config).length-1;
const statusKind=r=>isComplete(r)?'complete':r.status===0?'new':'review';
function statusBadge(r){return `<span class="badge ${isComplete(r)?'badge-complete':r.status>0?'badge-review':''}"><span class="dot"></span>${esc(steps(r.config)[r.status])}</span>`;}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4400);}
function button(label,action,ic='arrow',cls='btn'){return `<button type="button" class="${cls}" data-action="${action}">${ic?icon(ic):''}${label}</button>`;}
function render(){
  const names={overview:'Vista general',sectors:'Tipos de negocio',records:'Registros',workflow:'Flujo de trabajo',adapt:'Adaptabilidad'};
  document.getElementById('app').innerHTML=`<div class="shell"><div class="sidebar-backdrop ${mobileOpen?'show':''}" data-action="menu-close"></div><aside class="sidebar ${mobileOpen?'open':''}" aria-label="Navegación principal"><div class="brand"><svg class="brand-mark" viewBox="0 0 36 40" fill="none" aria-hidden="true"><path d="M18 2 33 10v18l-15 9L3 28V10L18 2Z" stroke="currentColor" stroke-width="2.3"/><path d="m3 10 15 9 15-9M18 19v18M10 6l15 9v9" stroke="currentColor" stroke-width="2.3"/></svg><div>Cargo<span class="flow">Flow</span><small>Operaciones que fluyen</small></div></div><div class="workspace"><div class="workspace-icon">${icon('building')}</div><div><b>Mi espacio de trabajo</b><span>Laboratorio de operaciones</span></div>${icon('down')}</div><p class="sidebar-label">Workspace</p><nav class="nav">${[['overview','grid','Vista general'],['sectors','building','Tipos de negocio'],['records','list','Registros'],['workflow','flow','Flujo de trabajo'],['adapt','layers','Adaptabilidad']].map(([key,ic,label])=>`<button type="button" data-view="${key}" class="${view===key?'active':''}" ${view===key?'aria-current="page"':''}>${icon(ic)}${label}${key==='records'?`<span class="nav-count">${records().length}</span>`:''}${key==='adapt'?'<span class="nav-count">LAB</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sandbox-note"><div class="mini-label">${icon('spark')} MODO EXPLORACIÓN</div><p>Un sistema. Distintos negocios.<br>Prueba cómo se adapta el flujo.</p><button type="button" data-action="start-tour">Iniciar recorrido ${icon('arrow')}</button><button type="button" data-action="reset">Restablecer demo</button></div><div class="profile"><div class="avatar">DI</div><div><b>Darío Idrovo</b><span>Espacio personal</span></div>${icon('lock')}</div></div></aside><div class="page"><header class="topbar"><div class="breadcrumb"><button type="button" class="mobile-menu" data-action="menu-toggle" aria-label="Abrir navegación" aria-expanded="${mobileOpen}">${icon('menu')}</button><span>Mi espacio</span>${icon('chevron')}<strong>${names[view]}</strong></div><div class="topbar-right"><span class="private-pill">${icon('lock')} Prototipo privado</span><span class="topbar-divider"></span><span class="badge-fake">Datos ficticios</span><div class="avatar top-user" aria-label="Darío Idrovo">DI</div></div></header><main class="main" id="main" tabindex="-1">${!storageOK?'<div class="storage-warning">El almacenamiento de este navegador no está disponible. Los cambios de esta sesión se perderán al cerrar o recargar la página.</div>':''}${({overview:overviewView,sectors:sectorsView,records:recordsView,workflow:workflowView,adapt:adaptView}[view])()}</main></div></div>`;
}
function heading(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function sectorStrip(){return `<div class="sector-strip"><div class="sector-icon">${icon(sector().icon)}</div><div><b>${sector().name} <span class="sector-tag">PLANTILLA ACTIVA</span></b><p>${esc(config().name)} · ${steps(config()).length} etapas configuradas</p></div><span class="sector-status"><span class="dot"></span> Espacio listo para explorar</span><button type="button" class="btn" data-view="sectors">Cambiar sector ${icon('repeat')}</button></div>`;}
function overviewView(){
  const all=records(),pending=all.filter(r=>r.status===0),review=all.filter(r=>r.status>0&&!isComplete(r)),done=all.filter(isComplete);
  return heading('TU OPERACIÓN, EN PERSPECTIVA','Todo en orden. Todo en movimiento.','Organiza, verifica y da seguimiento. Un flujo que crece con tu negocio.',button('Configurar flujo','workflow','settings','btn secondary-heading-action')+button(`Nueva ${sector().unit.toLowerCase()}`,'new','plus','btn btn-primary'))+
  sectorStrip()+`<section class="stats" aria-label="Resumen de registros">${[['Registros totales',all.length,'list','En esta plantilla',''],['Pendientes',pending.length,'clock','Listos para iniciar',''],['En proceso',review.length,'flow','Requieren seguimiento','accent'],['Completados',done.length,'circlecheck',`${all.length?Math.round(done.length/all.length*100):0}% del total de registros`,'']].map(([label,n,ic,note,cls])=>`<div class="stat ${cls}"><div class="stat-label">${label}${icon(ic)}</div><div class="stat-value">${String(n).padStart(2,'0')}</div><div class="stat-foot">${ic==='circlecheck'?'<b>✓</b> ':''}${note}</div></div>`).join('')}</section><div class="dashboard-grid"><div><section class="panel"><div class="panel-header"><div><h2>Actividad reciente</h2><p>El pulso de tus ${sector().plural}, en un solo lugar.</p></div><button type="button" class="btn btn-text" data-view="records">Ver todos ${icon('arrow')}</button></div>${tableTabs()}<div class="table-wrap" id="records-table">${recordTable(filteredRecords().slice(0,6))}</div><div class="table-footer"><span>${filteredRecords().length} registros de ejemplo · Fechas simuladas</span><span>Selecciona un registro ${icon('arrow')}</span></div></section>${journeyCard()}</div><aside class="side-column"><section class="panel workflow-panel"><div class="section-kicker">ASÍ FUNCIONA TU OPERACIÓN</div><div class="workflow-title"><h2>${esc(config().name)}</h2>${icon('flow')}</div>${flowNodes(config())}<div class="workflow-bottom"><span>${steps(config()).length} etapas · v${config().version}</span><button type="button" class="btn btn-text" data-view="workflow">Editar flujo ${icon('arrow')}</button></div></section><section class="adapt-card">${icon('layers')}<h3>Tu negocio cambia.<br>Tu sistema se adapta.</h3><p>Descubre qué se mantiene y qué puedes configurar para otro sector.</p><button type="button" data-view="adapt">Explorar adaptabilidad ${icon('arrow')}</button></section></aside></div>`;
}
function journeyCard(){const items=[['sector','sectors','Elige tu negocio','Carga, vehículos o equipos'],['config','workflow','Configura el flujo','Etapas y comprobaciones'],['record','new','Crea un registro','Prueba con un ejemplo'],['status','records','Sigue su estado','Avanza hasta el cierre']];return `<section class="guide"><div class="guide-top"><div class="guide-heading">${icon('spark')}<h3>Tu primera operación, paso a paso</h3></div><span class="guide-count">${Object.values(state.journey).filter(Boolean).length} de 4 explorados</span></div><div class="journey">${items.map(([key,action,title,note],i)=>`<button type="button" data-action="${action}" class="${state.journey[key]?'done':''}"><span class="step-circle">${state.journey[key]?icon('check'):i+1}</span><span><b>${title}</b><small>${note}</small></span></button>`).join('')}</div></section>`;}
function tableTabs(){const count=kind=>records().filter(r=>statusKind(r)===kind).length;return `<div class="tabs" role="group" aria-label="Filtrar registros por estado">${[['all','Todos',records().length],['new','Pendientes',count('new')],['review','En proceso',count('review')],['complete','Completados',count('complete')]].map(([key,label,n])=>`<button type="button" class="tab ${tableFilter===key?'active':''}" data-filter="${key}" aria-pressed="${tableFilter===key}">${label}<span>${n}</span></button>`).join('')}</div>`;}
function filteredRecords(){const q=search.trim().toLocaleLowerCase('es');return records().filter(r=>(tableFilter==='all'||statusKind(r)===tableFilter)&&(!q||[r.id,r.title,r.entity,r.owner,...Object.values(r.fields)].some(v=>String(v).toLocaleLowerCase('es').includes(q)))).sort((a,b)=>new Date(b.date)-new Date(a.date));}
function recordTable(rows){return `<table><thead><tr><th>REGISTRO / UNIDAD</th><th>ESTADO</th><th class="owner-col">RESPONSABLE</th><th class="date-col">FECHA</th><th aria-label="Acción"></th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td><button type="button" class="record-button" data-record="${r.id}"><span class="record-title">${esc(r.title)}</span><span class="record-id">${r.id} <span>·</span> ${esc(r.entity)}</span></button></td><td>${statusBadge(r)}</td><td class="owner-col"><span class="initials">${initials(r.owner)}</span>${esc(r.owner.split(' ')[0])} ${esc(r.owner.split(' ')[1][0])}.</td><td class="date-col">${fmtDate(r.date)}<div class="record-unit">${fmtTime(r.date)}</div></td><td class="table-action-cell"><button type="button" class="row-arrow" data-record="${r.id}" aria-label="Ver ${esc(r.id)}">${icon('chevron')}</button></td></tr>`).join(''):`<tr><td colspan="5"><div class="empty-state">${icon('search')}<b>No hay registros en esta vista</b>Prueba otro filtro o crea un registro de ejemplo.</div></td></tr>`}</tbody></table>`;}
function flowNodes(cfg){const notes=cfg.review?['Registro y datos iniciales','Comprobaciones y seguimiento','Validación y cierre']:['Registro y datos iniciales','Validación y cierre'];return steps(cfg).map((label,i)=>`<div class="flow-node"><span class="flow-number">${String(i+1).padStart(2,'0')}</span><div><b>${esc(label)}</b><small>${notes[i]}</small></div></div>`).join('');}
function sectorsView(){return heading('UN NÚCLEO COMÚN. MÚLTIPLES POSIBILIDADES.','¿Cómo funciona tu negocio?','Comienza con una plantilla. Cambia el contexto sin empezar desde cero.')+`<div class="note-box wide-note">${icon('layers')}<div><b>Lo esencial se reutiliza</b><p>Registros, responsables, etapas e historial comparten el mismo sistema. Cada sector aporta su vocabulario, sus campos y sus comprobaciones.</p></div></div><section class="sector-grid" aria-label="Plantillas de negocio">${Object.entries(SECTORS).map(([key,s],i)=>`<article class="business-card ${state.selected===key?'selected':''}"><span class="pill">${state.selected===key?'● ACTIVA':i===0?'PUNTO DE PARTIDA':'EXPLORAR DESPUÉS'}</span><div class="business-icon">${icon(s.icon)}</div><h2>${s.name}</h2><p>${s.description}</p><div class="field-chips">${s.fields.map(f=>`<span>${f.label}</span>`).join('')}</div><button type="button" class="btn ${state.selected===key?'btn-primary':''}" data-sector="${key}">${state.selected===key?'Continuar con esta plantilla':'Elegir plantilla'} ${icon('arrow')}</button></article>`).join('')}</section><div class="reuse-summary"><div><h3>Empieza por inspecciones. Crece cuando lo necesites.</h3><p>Estas son plantillas de exploración. Puedes mantener cada sector por separado y comparar sus necesidades.</p></div>${button('Comparar sectores','adapt','layers')}</div>`;}
function recordsView(){return heading('TRAZABILIDAD EN CADA PASO',`Tus ${sector().plural}, al día.`,'Abre un registro para revisar sus datos, comprobar requisitos y avanzar su estado.',button(`Nueva ${sector().unit.toLowerCase()}`,'new','plus','btn btn-primary'))+sectorStrip()+`<section class="panel"><div class="panel-header"><div><h2>Todos los registros</h2><p>${records().length} operaciones ficticias en ${sector().name.toLowerCase()}.</p></div><span class="pill">${icon('list')} ${steps(config()).length} etapas</span></div><div class="filter-row"><div class="search-box">${icon('search')}<input id="record-search" type="search" placeholder="Buscar por nombre, código o unidad…" aria-label="Buscar registros" value="${esc(search)}"></div><select id="record-status" aria-label="Filtrar estado"><option value="all" ${tableFilter==='all'?'selected':''}>Todos los estados</option><option value="new" ${tableFilter==='new'?'selected':''}>Pendientes</option><option value="review" ${tableFilter==='review'?'selected':''}>En proceso</option><option value="complete" ${tableFilter==='complete'?'selected':''}>Completados</option></select></div><div class="table-wrap" id="records-table">${recordTable(filteredRecords())}</div><div class="table-footer"><span id="result-count">${filteredRecords().length} registros encontrados</span><span>Datos ficticios · Sin operaciones reales</span></div></section>${journeyCard()}`;}
function workflowView(){const s=sector(),cfg=config();return heading('DISEÑA TU FORMA DE TRABAJAR','Un flujo a tu medida.','Ajusta etapas y requisitos. Los cambios se aplican a los nuevos registros.')+sectorStrip()+`<div class="settings-grid"><form class="panel form-panel" id="config-form"><div class="section-label"><b>01 · Tu flujo de trabajo</b><span class="common-tag">Núcleo reutilizable</span></div><p class="review-note">La estructura se mantiene entre sectores; el nombre y las etiquetas se configuran.</p><div class="form-group"><label for="flow-name">Nombre del flujo</label><input id="flow-name" name="flowName" value="${esc(cfg.name)}" required maxlength="50"><small>Un nombre claro para identificar esta operación.</small></div><div class="workflow-edit"><div class="form-group"><label for="stage-0">Etapa inicial</label><input id="stage-0" name="stage0" value="${esc(cfg.labels[0])}" maxlength="24" required></div>${icon('arrow')}<div class="form-group" id="review-stage-field" ${!cfg.review?'hidden':''}><label for="stage-1">Etapa de revisión</label><input id="stage-1" name="stage1" value="${esc(cfg.labels[1])}" maxlength="24" ${cfg.review?'required':''}></div><span id="review-stage-arrow" ${!cfg.review?'hidden':''}>${icon('arrow')}</span><div class="form-group"><label for="stage-2">Etapa de cierre</label><input id="stage-2" name="stage2" value="${esc(cfg.labels[2])}" maxlength="24" required></div></div><div class="toggle-row"><div><b>Incluir etapa de revisión</b><p>Añade una verificación antes del cierre.</p></div>${toggle('review',cfg.review,'Incluir etapa de revisión')}</div><div class="form-divider"></div><div class="section-label"><b>02 · Datos de ${s.unit.toLowerCase()}</b><span class="config-tag">Específico del sector</span></div><p class="review-note">${s.fieldIntro} Todos los campos se muestran; elige cuáles son obligatorios.</p>${s.fields.map(f=>`<div class="field-setting"><div><b>${f.label}</b><small>${f.type==='number'?'Valor numérico':f.type==='date'?'Fecha':f.type==='select'?'Selección de prioridad':'Texto'}</small></div><label class="checkbox-label"><input type="checkbox" aria-label="${f.label} obligatorio" name="required-${f.key}" ${cfg.requiredFields[f.key]?'checked':''}> Obligatorio</label></div>`).join('')}<div class="form-divider"></div><div class="section-label"><b>03 · Requisitos para cerrar</b><span class="config-tag">Configurable</span></div><div class="toggle-row"><div><b>Completar lista de comprobación</b><p>${s.checks.length} comprobaciones propias de este sector.</p></div>${toggle('requireChecklist',cfg.requireChecklist,'Completar lista de comprobación para cerrar')}</div><div class="toggle-row"><div><b>Incluir evidencia de ejemplo</b><p>Simula el requisito de evidencia antes del cierre.</p></div>${toggle('requireEvidence',cfg.requireEvidence,'Incluir evidencia para cerrar')}</div><div class="form-alert" id="config-error" role="alert" hidden></div><div class="form-actions"><small>Los registros existentes conservan su configuración.</small><button type="submit" class="btn btn-primary">${icon('check')} Guardar configuración</button></div></form><aside class="settings-sticky"><div class="preview-box"><div class="section-kicker">VISTA PREVIA DEL FLUJO</div><h3 id="preview-name">${esc(cfg.name)}</h3><div id="preview-flow">${flowNodes(cfg)}</div><p id="preview-requirements">${cfg.requireChecklist?'✓ Lista de comprobación requerida':'○ Lista de comprobación opcional'}<br>${cfg.requireEvidence?'✓ Evidencia requerida':'○ Evidencia opcional'}</p><span class="pill">Versión actual: ${cfg.version}</span></div><div class="spacer"></div><div class="note-box">${icon('info')}<div><b>Configurar no es desarrollar todo otra vez</b><p>El motor de estados y el historial siguen siendo los mismos. Cambian las reglas, los datos y las palabras de tu negocio.</p></div></div><div class="business-diff"><b>Esta plantilla incluye:</b><br>${s.checks.join(' · ')}.</div></aside></div>`;}
function toggle(name,checked,label){return `<label class="switch"><input type="checkbox" name="${name}" ${checked?'checked':''} aria-label="${label}"><span></span></label>`;}
function adaptView(){const a=SECTORS[compareFrom],b=SECTORS[compareTo],ca=state.configs[compareFrom],cb=state.configs[compareTo];return heading('CONSTRUYE UNA VEZ. CONFIGURA DESPUÉS.','El mismo núcleo. Otro contexto.','Explora qué puedes reutilizar y qué requiere decisiones específicas de cada negocio.')+`<div class="compare-grid"><section class="compare-card"><span class="common-tag">${icon('layers')} SE REUTILIZA</span><h2>La base de toda operación</h2><p>Capacidades comunes que no dependen del tipo de negocio.</p><ul class="feature-list">${[['file','Registro único','Código, nombre, responsable y fecha.'],['flow','Motor de estados','Etapas, avance controlado y reglas de cierre.'],['clock','Historial de actividad','Qué se registra y cómo cambia cada operación.']].map(([ic,title,note])=>`<li>${icon(ic)}<div><b>${title}</b><small>${note}</small></div></li>`).join('')}</ul></section><section class="compare-card"><span class="config-tag">${icon('settings')} SE CONFIGURA</span><h2>Lo que hace único a tu negocio</h2><p>Un conjunto de decisiones que da contexto al núcleo común.</p><ul class="feature-list">${[['list','Campos y vocabulario','Carga, vehículo o equipo; los datos cambian.'],['circlecheck','Comprobaciones y requisitos','Cada sector define lo que debe verificar.'],['building','Procesos especializados','Cobros, reservas o repuestos necesitan módulos propios.']].map(([ic,title,note])=>`<li>${icon(ic)}<div><b>${title}</b><small>${note}</small></div></li>`).join('')}</ul></section></div><div class="compare-controls"><div class="form-group"><label for="compare-from">Plantilla de origen</label><select id="compare-from">${sectorOptions(compareFrom)}</select></div>${icon('arrow')}<div class="form-group"><label for="compare-to">Explorar como</label><select id="compare-to">${sectorOptions(compareTo)}</select></div></div><section class="panel"><div class="panel-header"><div><h2>Compara antes de adaptar</h2><p>Los valores reflejan la configuración que has guardado.</p></div><span class="pill">${compareFrom===compareTo?'Misma plantilla':'Dos contextos'}</span></div><div class="table-wrap"><table class="comparison-table"><thead><tr><th>CAPACIDAD</th><th>${a.name.toUpperCase()}</th><th>${b.name.toUpperCase()}</th><th>¿QUÉ CAMBIA?</th></tr></thead><tbody><tr class="common-row"><td>Registro e historial</td><td>Código, responsable, fecha</td><td>Código, responsable, fecha</td><td><span class="common-tag">Se reutiliza</span></td></tr><tr class="common-row"><td>Motor de estados</td><td>Avance + validación de cierre</td><td>Avance + validación de cierre</td><td><span class="common-tag">Se reutiliza</span></td></tr><tr><td>Nombre del flujo</td><td>${esc(ca.name)}</td><td>${esc(cb.name)}</td><td><span class="config-tag">Configuración</span></td></tr><tr><td>Etapas</td><td>${steps(ca).map(esc).join(' → ')}</td><td>${steps(cb).map(esc).join(' → ')}</td><td><span class="config-tag">Configuración</span></td></tr><tr><td>Datos de la operación</td><td>${a.fields.map(f=>f.label).join(', ')}</td><td>${b.fields.map(f=>f.label).join(', ')}</td><td><span class="config-tag">Por sector</span></td></tr><tr><td>Comprobaciones</td><td>${a.checks.join(' · ')}</td><td>${b.checks.join(' · ')}</td><td><span class="config-tag">Por sector</span></td></tr><tr><td>Requisitos de cierre</td><td>${rulesText(ca)}</td><td>${rulesText(cb)}</td><td><span class="config-tag">Configuración</span></td></tr></tbody></table></div></section><div class="reuse-summary"><div><h3>Comprueba la reutilización, en la práctica.</h3><p>Copia las etapas y los requisitos de <span class="light-on-dark">${a.short.toLowerCase()}</span> a <span class="light-on-dark">${b.short.toLowerCase()}</span>.<br>La plantilla de destino conserva sus propios campos y su lista de comprobación.</p></div><button type="button" class="btn" data-action="reuse" ${compareFrom===compareTo?'disabled':''}>${icon('repeat')} Reutilizar este flujo</button></div><div class="note-box">${icon('info')}<div><b>El prototipo comprueba la base, no todos los procesos de cada industria.</b><p>${b.specificRule} La adaptación completa a un nuevo sector puede requerir lógica e integraciones adicionales.</p></div></div>`;}
function rulesText(c){return `${c.requireChecklist?'Lista completa':'Lista opcional'} · ${c.requireEvidence?'Evidencia requerida':'Evidencia opcional'}`;}
function sectorOptions(selected){return Object.entries(SECTORS).map(([key,s])=>`<option value="${key}" ${key===selected?'selected':''}>${s.name}</option>`).join('');}
function navigate(to){view=to;mobileOpen=false;tableFilter='all';search='';render();window.scrollTo({top:0,behavior:'instant'});document.getElementById('main').focus({preventScroll:true});}
function selectSector(key){state.selected=key;state.journey.sector=true;save();navigate('workflow');toast(`${SECTORS[key].name}: plantilla lista. Personaliza el flujo y guarda los cambios.`);}
function liveConfig(){const form=document.getElementById('config-form');if(!form)return null;const fd=new FormData(form);return {...config(),name:String(fd.get('flowName')||''),labels:[0,1,2].map(i=>String(fd.get(`stage${i}`)||'').trim()),review:fd.has('review'),requireChecklist:fd.has('requireChecklist'),requireEvidence:fd.has('requireEvidence'),requiredFields:Object.fromEntries(sector().fields.map(f=>[f.key,fd.has(`required-${f.key}`)]))};}
function updatePreview(){const c=liveConfig();if(!c)return;const review=document.getElementById('review-stage-field'),arrow=document.getElementById('review-stage-arrow');review.hidden=!c.review;arrow.hidden=!c.review;document.getElementById('stage-1').required=c.review;document.getElementById('preview-name').textContent=c.name||'Tu nuevo flujo';document.getElementById('preview-flow').innerHTML=flowNodes(c);document.getElementById('preview-requirements').innerHTML=`${c.requireChecklist?'✓ Lista de comprobación requerida':'○ Lista de comprobación opcional'}<br>${c.requireEvidence?'✓ Evidencia requerida':'○ Evidencia opcional'}`;}
function saveConfig(event){event.preventDefault();const c=liveConfig(),active=steps(c);const err=document.getElementById('config-error');if(!c.name.trim()||active.some(x=>!x.trim())){err.textContent='Escribe un nombre y una etiqueta para cada etapa activa.';err.hidden=false;return;}if(new Set(active.map(x=>x.toLocaleLowerCase('es'))).size!==active.length){err.textContent='Cada etapa debe tener un nombre diferente para identificar su estado.';err.hidden=false;return;}c.name=c.name.trim();c.version=config().version+1;state.configs[state.selected]=c;state.journey.config=true;save();render();toast('Configuración guardada. Se aplicará a los nuevos registros.');}

function showModal(content,kind,recordId=null){if(!currentModal)lastFocus=document.activeElement;currentModal={kind,recordId};document.getElementById('overlay-root').innerHTML=`<div class="backdrop" data-backdrop="true">${content}</div>`;document.body.style.overflow='hidden';const target=document.querySelector('.modal [autofocus], .modal .close-modal');target?.focus();}
function closeModal(){document.getElementById('overlay-root').innerHTML='';currentModal=null;document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();else document.getElementById('main')?.focus({preventScroll:true});}
function modalHeader(title,note){return `<header class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${note}</p></div><button type="button" class="icon-button close-modal" data-action="modal-close" aria-label="Cerrar ventana">${icon('close')}</button></header>`;}
function fieldInput(f,cfg){const required=cfg.requiredFields[f.key];const shared=`id="field-${f.key}" name="field-${f.key}" ${required?'required':''}`;return `<div class="form-group"><label for="field-${f.key}">${f.label} ${required?'*':'<span class="light-meta">(opcional)</span>'}</label>${f.type==='select'?`<select ${shared}><option value="">Seleccionar…</option>${f.options.map(o=>`<option>${o}</option>`).join('')}</select>`:`<input ${shared} type="${f.type||'text'}" ${f.type==='number'?'min="0" max="9999999" step="1"':'maxlength="100"'} placeholder="${esc(f.placeholder||'')}" ${f.key==='return'?'min="2026-01-01"':''}>`}</div>`;}
function openNew(){const s=sector(),cfg=config();showModal(`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${modalHeader(`Nueva ${s.unit.toLowerCase()}`,`${s.name} · ${esc(cfg.name)} · Datos ficticios`)}<div class="modal-body"><div class="tour-banner">${icon('spark')}<div><strong>Prueba sin empezar de cero.</strong><br>Completa el formulario o utiliza un ejemplo de esta plantilla.</div><button type="button" class="btn" data-action="fill-example">Usar ejemplo</button></div><form id="record-form"><div class="form-alert" id="record-error" role="alert" hidden></div><div class="section-label"><b>01 · Información del registro</b><span class="common-tag">Núcleo reutilizable</span></div><div class="form-row"><div class="form-group"><label for="record-title">Nombre del registro *</label><input id="record-title" name="title" placeholder="${esc(s.sampleTitle)}" required maxlength="70"></div><div class="form-group"><label for="record-owner">Responsable *</label><select id="record-owner" name="owner" required><option value="">Seleccionar responsable…</option>${OWNERS.map(o=>`<option>${o}</option>`).join('')}</select></div></div><div class="form-divider"></div><div class="section-label"><b>02 · Datos de ${s.unit.toLowerCase()}</b><span class="config-tag">Específico del sector</span></div><div class="form-row"><div class="form-group"><label for="record-entity">${s.entity} *</label><input id="record-entity" name="entity" placeholder="${esc(s.placeholder)}" required maxlength="100"></div>${s.fields.map(f=>fieldInput(f,cfg)).join('')}</div><div class="section-label"><b>03 · Lista de comprobación</b><span class="config-tag">${cfg.requireChecklist?'Obligatoria para cerrar':'Opcional'}</span></div><div class="checklist">${s.checks.map((c,i)=>`<label class="check-item"><input type="checkbox" name="check-${i}"><span>${c}</span></label>`).join('')}</div><p class="form-hint">Puedes registrar primero y completar estas comprobaciones antes del cierre.</p><div class="spacer"></div><div class="section-label"><b>04 · Evidencia y observaciones</b><span class="config-tag">${cfg.requireEvidence?'Evidencia requerida al cerrar':'Opcional'}</span></div><input type="hidden" name="evidence" value="false"><button type="button" class="evidence-button" data-action="evidence-new">${icon('image')} Añadir evidencia de ejemplo</button><p class="form-hint">Adjunto simulado. No se suben archivos ni imágenes reales.</p><div class="spacer"></div><div class="form-group"><label for="record-notes">Observaciones</label><textarea id="record-notes" name="notes" maxlength="500" placeholder="Añade un contexto breve para tu equipo…"></textarea></div><span class="light-meta">* Campos obligatorios · Se crea en estado «${esc(steps(cfg)[0])}»</span></form></div><footer class="modal-footer"><button type="button" class="btn btn-text" data-action="modal-close">Cancelar</button><button type="submit" form="record-form" class="btn btn-primary">${icon('plus')} Registrar ${s.unit.toLowerCase()}</button></footer></section>`,'new');}
function fillExample(){const form=document.getElementById('record-form');if(!form)return;const s=sector();form.elements.title.value=s.sampleTitle;form.elements.owner.value=OWNERS[0];form.elements.entity.value=s.sampleEntity;for(const f of s.fields)form.elements[`field-${f.key}`].value=f.sample;for(let i=0;i<s.checks.length;i++)form.elements[`check-${i}`].checked=true;form.elements.notes.value=s.sampleNotes;form.elements.evidence.value='true';updateEvidenceButton(form);toast('Ejemplo cargado. Revisa los datos y registra la operación.');}
function updateEvidenceButton(form){const attached=form.elements.evidence.value==='true';const btn=form.querySelector('[data-action="evidence-new"]');btn.classList.toggle('attached',attached);btn.innerHTML=attached?`${icon('file')} evidencia-demo.pdf · Simulada ${icon('check')}`:`${icon('image')} Añadir evidencia de ejemplo`;btn.setAttribute('aria-pressed',String(attached));}
function createRecord(event){event.preventDefault();const fd=new FormData(event.target),cfg=structuredClone(config()),s=sector(),title=String(fd.get('title')).trim(),entity=String(fd.get('entity')).trim(),fields=Object.fromEntries(s.fields.map(f=>[f.key,String(fd.get(`field-${f.key}`)||'').trim()]));if(!title||!entity||s.fields.some(f=>cfg.requiredFields[f.key]&&!fields[f.key])){const err=document.getElementById('record-error');err.textContent='Completa los campos obligatorios; los espacios en blanco no son datos válidos.';err.hidden=false;err.scrollIntoView({block:'center'});return;}const date=new Date().toISOString(),r={id:`${s.prefix}-${String(state.next++).padStart(4,'0')}`,sector:state.selected,title,entity,owner:String(fd.get('owner')),fields,status:0,date,config:cfg,checks:s.checks.map((_,i)=>fd.has(`check-${i}`)),evidence:fd.get('evidence')==='true',notes:String(fd.get('notes')||'').trim(),history:[{label:'Registro creado',date}]};state.records.unshift(r);state.journey.record=true;save();closeModal();view='records';tableFilter='all';search='';render();openDetail(r.id,true);toast(`${r.id} registrado. Ahora puedes avanzar su estado.`);}
function getRecord(id){return state.records.find(r=>r.id===id);}
function missingRequirements(r){const missing=[];if(r.config.requireChecklist&&r.checks.some(x=>!x))missing.push('Completa todas las comprobaciones.');if(r.config.requireEvidence&&!r.evidence)missing.push('Añade una evidencia de ejemplo.');return missing;}
function openDetail(id,fresh=false){const r=getRecord(id);if(!r)return;const s=SECTORS[r.sector],done=isComplete(r),nextLabel=steps(r.config)[r.status+1],closing=r.status+1===steps(r.config).length-1,missing=missingRequirements(r);showModal(`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${modalHeader(esc(r.title),`${r.id} · ${s.name} · Registro ficticio`)}<div class="modal-body">${fresh?`<div class="success-banner">${icon('circlecheck')} Registro creado. Sigue su recorrido hasta el cierre.</div>`:''}<div class="detail-summary"><div><small>${s.entity}</small><b>${esc(r.entity)}</b></div><div><small>Responsable</small><b><span class="initials">${initials(r.owner)}</span>${esc(r.owner)}</b></div><div><small>Creado</small><b>${fmtDate(r.date)} ${new Date(r.date).getFullYear()} · ${fmtTime(r.date)}</b></div></div><div class="section-label"><b>Estado de la operación</b>${statusBadge(r)}</div><div class="status-path">${steps(r.config).map((label,i)=>`<div class="status-step ${i<r.status?'done':i===r.status?'active':''}"><span>${i<r.status?icon('check'):i+1}</span><b>${esc(label)}</b></div>`).join('')}</div><div class="section-label"><b>Datos de ${s.unit.toLowerCase()}</b><span class="config-tag">Específico del sector</span></div><div class="detail-fields">${s.fields.map(f=>`<div><span>${f.label}</span><b>${esc(r.fields[f.key]||'Sin especificar')}</b></div>`).join('')}</div><div class="section-label"><b>Lista de comprobación</b><span class="config-tag">${r.config.requireChecklist?'Requerida para cerrar':'Opcional'}</span></div>${s.checks.map((c,i)=>done?`<div class="detail-check ${r.checks[i]?'':'missing'}">${icon(r.checks[i]?'circlecheck':'clock')}${c}</div>`:`<label class="check-item"><input type="checkbox" data-detail-check="${i}" ${r.checks[i]?'checked':''}> ${c}</label>`).join('')}<div class="spacer"></div><button type="button" class="evidence-button ${r.evidence?'attached':''}" data-action="evidence-detail" ${done?'disabled':''}>${icon(r.evidence?'file':'image')} ${r.evidence?'evidencia-demo.pdf · Adjunto simulado':'Añadir evidencia de ejemplo'}</button><p class="form-hint">El adjunto es ficticio. No se ha subido ningún archivo real.</p>${!done&&closing&&missing.length?`<div id="detail-requirements" class="validation-note" role="status"><b>Antes de cerrar:</b><br>${missing.map(esc).join('<br>')}<br>Los requisitos se validan al avanzar.</div>`:''}${r.notes?`<div class="detail-section section-label"><b>Observaciones</b></div><div class="record-note">${esc(r.notes)}</div>`:''}<div class="detail-section section-label"><b>Historial de actividad</b><span class="common-tag">Núcleo reutilizable</span></div><ul class="history">${r.history.map(h=>`<li><span class="dot"></span><span>${esc(h.label)}</span><time datetime="${esc(h.date)}">${fmtDate(h.date)} · ${fmtTime(h.date)}</time></li>`).join('')}</ul><div class="config-version">${esc(r.config.name)} · Configuración v${r.config.version} · Se conserva la versión usada al crear el registro.</div><div id="advance-error" class="form-alert" role="alert" hidden></div></div><footer class="modal-footer"><button type="button" class="btn btn-text" data-action="modal-close">Cerrar detalle</button>${done?`<span class="done-note">${icon('circlecheck')} Operación completada</span>`:`<button type="button" class="btn btn-primary" data-action="advance">${icon(closing?'check':'arrow')} ${closing?'Finalizar como':'Avanzar a'} «${esc(nextLabel)}»</button>`}</footer></section>`,'detail',id);}
function advance(){const r=getRecord(currentModal?.recordId);if(!r||isComplete(r))return;const closing=r.status+1===steps(r.config).length-1;if(closing){const missing=missingRequirements(r);if(missing.length){const err=document.getElementById('advance-error');err.textContent=`No se puede cerrar todavía. ${missing.join(' ')}`;err.hidden=false;err.scrollIntoView({block:'center',behavior:'smooth'});toast('Cierre bloqueado: revisa los requisitos pendientes.');return;}}r.status++;r.history.push({label:`Estado: ${steps(r.config)[r.status]}`,date:new Date().toISOString()});if(isComplete(r))state.journey.status=true;save();render();openDetail(r.id);toast(isComplete(r)?'Operación completada. El historial conserva su recorrido.':`Estado actualizado a «${steps(r.config)[r.status]}».`);}
function openReuse(){const a=SECTORS[compareFrom],b=SECTORS[compareTo];if(compareFrom===compareTo)return;showModal(`<section class="modal modal-sm" role="dialog" aria-modal="true" aria-labelledby="modal-title">${modalHeader('Reutiliza la base. Cambia el contexto.','Una prueba concreta de adaptabilidad')}<div class="modal-body"><p>Se copiarán las <b>etapas y los requisitos de cierre</b> de ${a.name.toLowerCase()} a ${b.name.toLowerCase()}. Esto reemplaza esa parte de la configuración de destino.<br><br>${b.name} conservará sus propios <b>campos, comprobaciones y nombre del flujo</b>. Los registros existentes mantienen su configuración original.</p></div><footer class="modal-footer"><button class="btn btn-text" type="button" data-action="modal-close">Cancelar</button><button class="btn btn-primary" type="button" data-action="reuse-confirm">${icon('repeat')} Copiar y explorar</button></footer></section>`,'reuse');}
function confirmReuse(){const source=state.configs[compareFrom],target=state.configs[compareTo];state.configs[compareTo]={...target,labels:[...source.labels],review:source.review,requireChecklist:source.requireChecklist,requireEvidence:source.requireEvidence,version:target.version+1};state.selected=compareTo;state.journey.sector=true;save();closeModal();navigate('workflow');toast('Flujo reutilizado. Los campos y las comprobaciones siguen siendo propios del nuevo sector.');}
function resetDialog(){showModal(`<section class="modal modal-sm" role="dialog" aria-modal="true" aria-labelledby="modal-title">${modalHeader('Volver al punto de partida','Solo se restablece esta demostración')}<div class="modal-body"><p>Se eliminarán los registros y ajustes que has creado en este navegador y volverán los ejemplos iniciales de los tres sectores.</p></div><footer class="modal-footer"><button class="btn btn-text" type="button" data-action="modal-close">Conservar cambios</button><button class="btn btn-primary" type="button" data-action="reset-confirm">Restablecer demo</button></footer></section>`,'reset');}

document.addEventListener('click',event=>{
  const el=event.target.closest('[data-action],[data-view],[data-sector],[data-record],[data-filter]');
  if(!el){if(event.target.dataset.backdrop)closeModal();return;}
  if(el.dataset.view){navigate(el.dataset.view);return;}
  if(el.dataset.sector){selectSector(el.dataset.sector);return;}
  if(el.dataset.record){openDetail(el.dataset.record);return;}
  if(el.dataset.filter){tableFilter=el.dataset.filter;render();return;}
  const action=el.dataset.action;
  if(['overview','sectors','workflow','records','adapt'].includes(action)){navigate(action);return;}
  if(action==='new')openNew();
  else if(action==='fill-example')fillExample();
  else if(action==='modal-close')closeModal();
  else if(action==='advance')advance();
  else if(action==='evidence-new'){const form=document.getElementById('record-form');form.elements.evidence.value=form.elements.evidence.value==='true'?'false':'true';updateEvidenceButton(form);}
  else if(action==='evidence-detail'){const r=getRecord(currentModal.recordId);if(!isComplete(r)){r.evidence=!r.evidence;save();openDetail(r.id);}}
  else if(action==='reuse')openReuse();
  else if(action==='reuse-confirm')confirmReuse();
  else if(action==='reset')resetDialog();
  else if(action==='reset-confirm'){state=seedState();save();closeModal();navigate('overview');toast('Demo restablecida. Todo listo para volver a explorar.');}
  else if(action==='menu-toggle'){mobileOpen=!mobileOpen;render();}
  else if(action==='menu-close'){mobileOpen=false;render();}
  else if(action==='start-tour'){state.journey={sector:false,config:false,record:false,status:false};save();navigate('sectors');toast('Paso 1 de 4: elige una plantilla para comenzar.');}
});
document.addEventListener('submit',event=>{if(event.target.id==='config-form')saveConfig(event);else if(event.target.id==='record-form')createRecord(event);});
document.addEventListener('input',event=>{if(event.target.closest('#config-form'))updatePreview();if(event.target.id==='record-search'){search=event.target.value;document.getElementById('records-table').innerHTML=recordTable(filteredRecords());document.getElementById('result-count').textContent=`${filteredRecords().length} registros encontrados`;}});
document.addEventListener('change',event=>{
  if(event.target.id==='record-status'){tableFilter=event.target.value;document.getElementById('records-table').innerHTML=recordTable(filteredRecords());document.getElementById('result-count').textContent=`${filteredRecords().length} registros encontrados`;}
  if(event.target.id==='compare-from'){compareFrom=event.target.value;render();document.getElementById('compare-from').focus();}
  if(event.target.id==='compare-to'){compareTo=event.target.value;render();document.getElementById('compare-to').focus();}
  if(event.target.hasAttribute('data-detail-check')){const r=getRecord(currentModal?.recordId);if(r&&!isComplete(r)){r.checks[Number(event.target.dataset.detailCheck)]=event.target.checked;save();const pending=document.getElementById('detail-requirements');if(pending){const missing=missingRequirements(r);pending.hidden=missing.length===0;pending.innerHTML='<b>Antes de cerrar:</b><br>'+missing.map(esc).join('<br>')+'<br>Los requisitos se validan al avanzar.';}const alert=document.getElementById('advance-error');if(alert)alert.hidden=true;}}
});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(currentModal)closeModal();else if(mobileOpen){mobileOpen=false;render();}}if(event.key==='Tab'&&currentModal){const nodes=[...document.querySelectorAll('.modal button:not([disabled]),.modal input:not([type="hidden"]),.modal select,.modal textarea')].filter(el=>el.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
render();
